fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // For three points on a line, the sum of absolute distances to a meeting point
    // is minimized at the median point. The minimal total distance equals
    // max - min (since the median lies between them).
    let min_v = x1.min(x2).min(x3);
    let max_v = x1.max(x2).max(x3);
    max_v - min_v
}